import {choices,validateProfile,validatePacket} from './protocol.js';
const $=id=>document.getElementById(id);
let study,config,state,index=0,ready=false,objectURL=null,loadNumber=0,saving=false,storageOK=true;
const notice=(message,error=false)=>{$('notice').textContent=message;$('notice').className=error?'error':'';};
const token=()=>Array.from(crypto.getRandomValues(new Uint8Array(32)),b=>b.toString(16).padStart(2,'0')).join('');
const storageKey=()=>`snel-reader-v2:${study.packageFingerprint}`;
function fresh(){return {packetType:study.packetType,schemaVersion:2,packageFingerprint:study.packageFingerprint,originalPackageFingerprint:study.originalPackageFingerprint,consentVersion:study.consentVersion,submissionId:crypto.randomUUID(),submissionToken:token(),profile:null,records:study.images.map(r=>({recordId:r.id,imageSha256:r.sha256,values:{guess:''},updatedAt:null})),index:0,receipt:null};}
function save(){state.index=index;try{localStorage.setItem(storageKey(),JSON.stringify(state));}catch{storageOK=false;notice('This browser cannot save your progress. Keep this tab open and download a backup before leaving.',true);}}
function show(id){for(const part of ['welcome','review','complete'])$(part).hidden=part!==id;}
function profileToForm(){if(!state.profile)return;const p=state.profile;$('name').value=p.name;$('experience').value=p.experienceYears;for(const e of document.querySelectorAll('[name=authorship]'))e.checked=e.value===p.authorshipConsent;$('agreement').checked=p.dataSharingConsent;}
function readProfile(){return validateProfile({name:$('name').value,experienceYears:$('experience').value===''?NaN:Number($('experience').value),authorshipConsent:document.querySelector('[name=authorship]:checked')?.value,dataSharingConsent:$('agreement').checked});}
function completed(){return state.records.filter(r=>choices.includes(r.values.guess)).length;}
function update(){const n=completed();$('count').textContent=`${n} of 100 answered`;$('progress').value=n;$('image-title').textContent=`Image ${index+1} of 100`;$('jump').value=String(index);$('previous').disabled=index===0;$('next').textContent=index===99?'Finish':'Next';$('finish').hidden=n!==100;for(const b of document.querySelectorAll('[data-guess]')){b.setAttribute('aria-pressed',String(state.records[index].values.guess===b.dataset.guess));b.disabled=!ready;}for(let i=0;i<100;i++)$('jump').options[i].textContent=`${i+1}${state.records[i].values.guess?' ✓':''}`;}
async function render(){show('review');ready=false;const current=++loadNumber;const row=study.images[index];$('image-state').hidden=false;$('image-state').textContent='Loading image…';$('image').hidden=true;update();try{const r=await fetch(row.path);if(!r.ok)throw Error();const bytes=await r.arrayBuffer();const digest=Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',bytes)),b=>b.toString(16).padStart(2,'0')).join('');if(digest!==row.sha256||bytes.byteLength!==row.bytes)throw Error();if(current!==loadNumber)return;if(objectURL)URL.revokeObjectURL(objectURL);objectURL=URL.createObjectURL(new Blob([bytes],{type:'image/png'}));const img=$('image');img.src=objectURL;await img.decode();if(current!==loadNumber)return;img.alt=`Endoscopy image ${index+1} for assessment`;img.hidden=false;$('image-state').hidden=true;ready=true;update();}catch{if(current===loadNumber){$('image-state').textContent='The image could not be verified or loaded. Use Next, then Previous to retry.';}}}
function navigate(i){index=Math.max(0,Math.min(99,i));save();render();}
function finish(){if(completed()!==100){notice('Please answer all 100 images before submitting.',true);const i=state.records.findIndex(r=>!r.values.guess);navigate(i);return;}show('complete');$('complete-title').textContent=state.receipt?'Assessment received':'Ready to submit';$('summary').textContent=`${state.profile.name} · ${state.profile.experienceYears} years of experience · 100 images answered`;$('submit-actions').hidden=Boolean(state.receipt);$('receipt').textContent=state.receipt?`Thank you. Your response was saved. Confirmation: ${state.receipt.id}.` : (!config.collectionEnabled?'Preview only. Your answers have not been sent to the study team. Automatic submission will be available after the study opens.':'');$('submit').disabled=!config.collectionEnabled;$('submission-info').hidden=!config.collectionEnabled;$('complete-title').focus();}
function packet(){return {...validatePacket(state,study),exportedAt:new Date().toISOString(),receipt:state.receipt??null};}
function download(){try{const p=packet();const url=URL.createObjectURL(new Blob([JSON.stringify(p,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=`endoscopy-reader-${state.submissionId}${state.receipt?'-submitted':'-backup'}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}catch(e){notice(e.message,true);}}
$('profile').addEventListener('submit',event=>{event.preventDefault();if(!config.collectionEnabled&&!config.previewMode){notice('The study is not open yet. Please return when the study team shares the invitation.',true);return;}try{state.profile=readProfile();save();notice(storageOK?(config.previewMode?'Preview only. Use test details; responses cannot be submitted yet.':''):'Progress cannot be saved in this browser. Download a backup before leaving.',!storageOK);render();}catch(e){notice(e.message,true);}});
for(const b of document.querySelectorAll('[data-guess]'))b.addEventListener('click',()=>{if(!ready||state.receipt)return;state.records[index].values.guess=b.dataset.guess;state.records[index].updatedAt=new Date().toISOString();save();update();});
$('previous').onclick=()=>navigate(index-1);$('next').onclick=()=>index===99?finish():navigate(index+1);$('jump').onchange=e=>navigate(Number(e.target.value));$('pending').onclick=()=>{for(let n=1;n<=100;n++){const i=(index+n)%100;if(!state.records[i].values.guess){navigate(i);return;}}finish();};
$('finish').onclick=finish;$('return').onclick=()=>render();$('profile-edit').onclick=()=>{profileToForm();show('welcome');};$('backup').onclick=download;$('final-backup').onclick=download;$('import-open').onclick=()=>$('import').click();
$('import').onchange=async event=>{const f=event.target.files[0];if(!f)return;try{if(f.size>150000)throw Error('The backup file is too large.');const parsed=validatePacket(JSON.parse(await f.text()),study);if(!confirm('Replace this browser’s current draft with the selected backup?'))return;state={...parsed,receipt:null,index:0};index=0;save();profileToForm();notice('Backup restored. Submit to confirm whether it has already been received.');if(config.collectionEnabled||config.previewMode)render();}catch(e){notice(e.message,true);}event.target.value='';};
$('submit').onclick=async()=>{if(saving||state.receipt)return;if(!config.collectionEnabled){notice('The study is not open for submissions yet.',true);return;}saving=true;$('submit').disabled=true;$('submit').textContent='Saving…';$('receipt').textContent='';try{const p=validatePacket(state,study,true);const response=await fetch(`${config.apiBase}/api/responses`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(p),signal:AbortSignal.timeout(30000)});const result=await response.json();if(!response.ok||!result.receipt||result.receipt.id!==state.submissionId)throw Error(result.error||'The response was not confirmed.');state.receipt=result.receipt;save();notice('');finish();}catch(e){$('receipt').textContent=`We could not confirm that your response was saved. Your answers are still here. Please retry, or download a backup and contact the study team. ${e.message}`;}finally{saving=false;$('submit').disabled=false;$('submit').textContent='Submit assessment';}};
try{[study,config]=await Promise.all(['study.json','config.json'].map(async p=>{const r=await fetch(p,{cache:'no-store'});if(!r.ok)throw Error('The study could not be loaded. Please refresh.');return r.json();}));for(let i=0;i<100;i++){const o=document.createElement('option');o.value=String(i);o.textContent=String(i+1);$('jump').append(o);}state=fresh();try{const raw=localStorage.getItem(storageKey());if(raw){const saved=JSON.parse(raw);const v=validatePacket(saved,study);state={...v,index:Number.isInteger(saved.index)?Math.max(0,Math.min(99,saved.index)):0,receipt:null};/* Server confirms a previously submitted response on resubmission. */index=state.index;}}catch{notice('No valid saved draft was found. You can restore a downloaded backup.');}profileToForm();$('start').disabled=!config.collectionEnabled&&!config.previewMode;if(config.previewMode){notice('Preview only. Use test details; responses cannot be submitted yet.');$('start').textContent=state.profile?'Resume preview':'Try the preview';}else if(!config.collectionEnabled){notice('The study is being prepared and is not open for responses yet.');$('start').textContent='Study not yet open';}else{notice('');$('start').textContent=state.profile?'Resume assessment':'Begin assessment';}show('welcome');}catch(e){notice(e.message,true);}
